use postgres::{Client,Transaction};
use std::{fs::File, io, path::{Component,Path}};
#[derive(Debug)]
pub enum ImportError { Database(postgres::Error), File(io::Error), UnsafePrefix, ImportInProgress, AmbiguousChecksum, InvalidDemo, ForeignChecksum(&'static str) }
impl From<postgres::Error> for ImportError { fn from(e:postgres::Error)->Self{Self::Database(e)} }
impl From<io::Error> for ImportError { fn from(e:io::Error)->Self{Self::File(e)} }
