fn copy_file(tx:&mut Transaction<'_>,sql:&str,path:&Path)->Result<u64,ImportError>{let mut input=File::open(path)?;let mut writer=tx.copy_in(sql)?;io::copy(&mut input,&mut writer)?;Ok(writer.finish()?)}
fn file(root:&Path,prefix:&str,suffix:&str)->std::path::PathBuf{root.join(format!("{prefix}{suffix}"))}
/// Caller must independently own/authorize client and input directory. No caller is wired yet.
/// Uses one transaction, serial COPY and preserves CSV files; these differ from original.
/// Parent-table write contention fails closed; row/FK locks have a transaction-local timeout.
/// Process setup and file/COPY operations do not have a hard deadline.
/// Caller must still validate schema, dependent data, filesystem authority and service lifecycle.
pub fn import_match(client:&mut Client,root:&Path,prefix:&str,checksum:&str)->Result<(),ImportError>{
 let mut components=Path::new(prefix).components();if prefix.is_empty()||!matches!(components.next(),Some(Component::Normal(_)))||components.next().is_some()||prefix.contains(['/', '\\', '\0'])||checksum.is_empty(){return Err(ImportError::UnsafePrefix)}
 let mut tx=client.transaction()?;
 tx.batch_execute("SET LOCAL lock_timeout = '2s'")?;
 let locked:bool=tx.query_one("SELECT pg_catalog.pg_try_advisory_xact_lock(pg_catalog.hashtextextended($1::text,0))",&[&checksum])?.get(0);if !locked{return Err(ImportError::ImportInProgress)}
 if let Err(e)=tx.batch_execute("LOCK TABLE public.demos,public.matches IN SHARE ROW EXCLUSIVE MODE NOWAIT") {if e.code().map(|x|x.code())==Some("55P03"){return Err(ImportError::ImportInProgress)}return Err(e.into())}
 for table in ["demos","matches"] {let query=format!("SELECT checksum FROM \"public\".\"{table}\" WHERE checksum=$1 FOR UPDATE");for row in tx.query(&query,&[&checksum])?{let found:String=row.get(0);if found.as_bytes()!=checksum.as_bytes(){return Err(ImportError::AmbiguousChecksum)}}}
 tx.execute("DELETE FROM public.matches WHERE checksum=$1 AND pg_catalog.convert_to(checksum::text,'UTF8')=pg_catalog.convert_to($1::text,'UTF8')",&[&checksum])?;
 tx.batch_execute("CREATE TEMP TABLE pg44_demo(c0 text,c1 text,c2 text,c3 text,c4 text,c5 text,c6 text,c7 text,c8 text,c9 text,c10 text,c11 text,c12 text,c13 text,c14 text,c15 text) ON COMMIT DROP")?;
 copy_file(&mut tx,"COPY pg_temp.pg44_demo FROM STDIN WITH (FORMAT csv, ENCODING 'UTF8', FORCE_NOT_NULL (c0,c1,c2,c3,c4,c5,c6,c7,c8,c9,c10,c11,c12,c13,c14,c15))",&file(root,prefix,"_demo.csv"))?;
 let rows=tx.query_one("SELECT count(*)::bigint,count(*) FILTER(WHERE pg_catalog.convert_to(c0, 'UTF8') IS DISTINCT FROM pg_catalog.convert_to($1::text, 'UTF8'))::bigint FROM pg_temp.pg44_demo",&[&checksum])?;if rows.get::<_,i64>(0)!=1||rows.get::<_,i64>(1)!=0{return Err(ImportError::InvalidDemo)}
 let affected=tx.execute("INSERT INTO public.demos(checksum,game,name,date,source,type,share_code,map_name,server_name,client_name,tick_count,tickrate,framerate,duration,network_protocol,build_number) SELECT c0,c1,c2,c3::timestamptz,c4,c5,c6,c7,c8,c9,substring(c10 from '^[+-]?[0-9]+')::integer,substring(c11 from '^[+-]?[0-9]+')::integer,c12::double precision,c13::double precision,substring(c14 from '^[+-]?[0-9]+')::integer,substring(c15 from '^[+-]?[0-9]+')::integer FROM pg_temp.pg44_demo WHERE true ON CONFLICT (checksum) DO UPDATE SET map_name=EXCLUDED.map_name,tick_count=EXCLUDED.tick_count,tickrate=EXCLUDED.tickrate,framerate=EXCLUDED.framerate,duration=EXCLUDED.duration,share_code=EXCLUDED.share_code WHERE pg_catalog.convert_to(public.demos.checksum::text, 'UTF8')=pg_catalog.convert_to(EXCLUDED.checksum::text, 'UTF8')",&[])?;if affected!=1{return Err(ImportError::AmbiguousChecksum)}
 for spec in SPECS {
  let cols=spec.columns.iter().map(|x|format!("\"{x}\"")).collect::<Vec<_>>().join(",");
  let table=format!("\"public\".\"{}\"",spec.table);
  tx.batch_execute(&format!("CREATE TEMP TABLE pg44_stage ON COMMIT DROP AS SELECT {cols} FROM {table} WITH NO DATA"))?;
  copy_file(&mut tx,&format!("COPY pg_temp.pg44_stage ({cols}) FROM STDIN WITH (FORMAT csv, ENCODING 'UTF8')"),&file(root,prefix,spec.suffix))?;
  let bad:i64=tx.query_one(&format!("SELECT count(*)::bigint FROM pg_temp.pg44_stage WHERE pg_catalog.convert_to(\"{}\"::text, 'UTF8') IS DISTINCT FROM pg_catalog.convert_to($1::text, 'UTF8')",spec.checksum_column),&[&checksum])?.get(0);
  if bad!=0{return Err(ImportError::ForeignChecksum(spec.table))}
  if spec.table=="matches"&&tx.query_one("SELECT count(*)::bigint FROM pg_temp.pg44_stage",&[])?.get::<_,i64>(0)!=1{return Err(ImportError::InvalidDemo)}
  tx.batch_execute(&format!("INSERT INTO {table} ({cols}) SELECT {cols} FROM pg_temp.pg44_stage; DROP TABLE pg_temp.pg44_stage"))?;
 }
 tx.commit()?;Ok(())
}
